python3 - <<'PY'
import json, os, re
data_dir = '/app/data'
out_dir = '/app/output'
os.makedirs(out_dir, exist_ok=True)
def load(name):
    with open(os.path.join(data_dir, name), 'r') as f:
        return json.load(f)
route = load('route.json')
prefs = load('preferences.json')
relationships = load('relationships.json')
local_pref = load('local_pref.json')
possible_solutions = load('possible_solutions.json')
topology = load('topology.json')
route_events = load('route_events.json')
# --- Sanity: build relationship lookup ---
rel = {(r['from'], r['to']): r['type'] for r in relationships}
# --- Oscillation detection: preference cycle in prefer_via graph ---
prefer_via = {int(k): int(v['prefer_via']) for k, v in prefs.items()}
cycle = None
visited_global = set()
for start in list(prefer_via):
    if start in visited_global:
        continue
    path = []
    seen_index = {}
    cur = start
    while cur in prefer_via:
        if cur in seen_index:
            cycle = path[seen_index[cur]:]
            break
        if cur in visited_global:
            break
        seen_index[cur] = len(path)
        path.append(cur)
        cur = prefer_via[cur]
    visited_global.update(path)
    if cycle:
        break
oscillation_detected = cycle is not None
oscillation_cycle = cycle if cycle else []
affected_ases = sorted(set(oscillation_cycle)) if oscillation_detected else []
# --- Route leak detection ---
# Valley-free: if learned from provider/peer, can only export to customers.
# We treat route_events as observed exports and validate violation.
leaks = []
for ev in route_events:
    src_type = ev['source_type']
    dst_type = ev['destination_type']
    violates = (src_type in ('provider', 'peer')) and (dst_type in ('provider', 'peer'))
    # Cross-check types against relationships when present
    adv = ev['advertiser_asn']
    src = ev['source_asn']
    dst = ev['destination_asn']
    rel_src = rel.get((src, adv))  # relationship of src -> advertiser (how advertiser learned)
    rel_dst = rel.get((adv, dst))  # relationship of advertiser -> dst (export link)
    # If we have relationship info and it contradicts, prefer relationship-derived types.
    # Map relationship edge type to the perspective in event fields:
    # If src -> adv is 'provider', advertiser learned from provider.
    # If adv -> dst is 'peer', advertiser exported to peer.
    if rel_src and rel_src != src_type:
        src_type = rel_src
    if rel_dst and rel_dst != dst_type:
        dst_type = rel_dst
    violates = (src_type in ('provider', 'peer')) and (dst_type in ('provider', 'peer'))
    if violates:
        leaks.append({
            'leaker_as': adv,
            'source_as': src,
            'destination_as': dst,
            'source_type': src_type,
            'destination_type': dst_type,
        })
route_leak_detected = len(leaks) > 0
# --- Solution evaluation heuristics ---
def resolves_oscillation(sol: str) -> bool:
    s = sol.lower().strip()
    # Prohibited / non-policy fixes don't count as valid resolution
    if 'disable hub peering' in s:
        return False
    # Explicitly break the preference cycle
    if 'update routing preference' in s and ('stop preferring' in s or 'stop preferring routes via' in s):
        return True
    if s.startswith('set route preference hierarchy'):
        return True
    # Break one leg by preventing peer-learned routes from being re-advertised
    if 'filter out routes learned from hub2 before re-advertising' in s or 'filter out routes learned from hub1 before re-advertising' in s:
        return True
    if 'configure export policy on hub1 to filter out routes learned from hub2' in s or 'configure export policy on hub2 to filter out routes learned from hub1' in s:
        return True
    # Everything else does not explicitly break the preference-cycle condition
    return False
def resolves_route_leak(sol: str) -> bool:
    s = sol.lower().strip()
    if 'disable hub peering' in s:
        return False
    # Direct export controls to stop provider->peer propagation
    if 'no-export of provider routes to peer' in s:
        return True
    if 'block announcing provider routes' in s and 'to peer' in s:
        return True
    if 'export policy' in s and 'block announcing provider routes' in s:
        return True
    # Import-side containment: stop accepting leaked provider routes from the peer
    if 'ingress filtering' in s and 'reject routes' in s and 'virtual wan asn 65001' in s:
        return True
    return False
solution_results = {
    sol: {
        'oscillation_resolved': bool(resolves_oscillation(sol)) if oscillation_detected else False,
        'route_leak_resolved': bool(resolves_route_leak(sol)) if route_leak_detected else False,
    }
    for sol in possible_solutions
}
report = {
    'oscillation_detected': oscillation_detected,
    'oscillation_cycle': oscillation_cycle,
    'affected_ases': affected_ases,
    'route_leak_detected': route_leak_detected,
    'route_leaks': leaks,
    'solution_results': solution_results,
}
out_path = os.path.join(out_dir, 'oscillation_report.json')
with open(out_path, 'w') as f:
    json.dump(report, f, indent=2, sort_keys=False)
print(out_path)
print(json.dumps(report, indent=2)[:2000])
